-- ----------------------------
-- Table structure for sys_mail_tasks
-- ----------------------------
DROP TABLE IF EXISTS `sys_mail_tasks`;
CREATE TABLE `sys_mail_tasks`  (
  `sys_mail_tasks_id` bigint NOT NULL COMMENT '邮件任务表ID',
  `subject` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '邮件主题',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '邮件正文（HTML或者纯文本）',
  `sender` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '发件人邮箱地址',
  `sender_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '发件人姓名',
  `recipients` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '收件人列表',
  `cc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '抄送列表',
  `bcc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '密送列表',
  `template_id` bigint NULL DEFAULT NULL COMMENT '使用的邮件模板表ID(可选)',
