INSERT INTO `onl_drag_dataset_head` VALUES ('1517020649262972930', '项目性质收入统计SQL', '', '1516743332632494082', '1011872166805864448', 'SELECT\n id,\n nature,\n insurance_fee,\n  risk_consulting_fee,\n  evaluation_fee,\n insurance_evaluation_fee,\n bidding_consulting_fee,\n interol_consulting_fee,\n (\n   insurance_fee + \n    risk_consulting_fee + \n    risk_consulting_fee + \n    evaluation_fee + \n   insurance_evaluation_fee + \n   bidding_consulting_fee + \n   interol_consulting_fee\n  ) AS \'total\'\nFROM\n  jeecg_project_nature_income', '', '', 'sql', 'get', '2022-04-21 14:01:22', 'admin', '2024-10-31 15:51:07', 'admin', NULL, 1);
