INSERT INTO `sys_log_operation` VALUES (1784426829407977473, 'admin', '通知公告-新增', '192.168.10.131', 'ADD', '新增通知公告信息', 'POST', '/system/sys/notice/save', '{\"title\":\"关于XX公司年度总结会议的通知\",\"content\":\"<p style=\\\"text-align: start;\\\">各位同事：</p><p> &nbsp; &nbsp; &nbsp; &nbsp;公司定于本月XX日召开年度总结会议，请各位同仁准时参加，共同回顾过去一年的成绩与不足，展望未来的发展方向。会议地点为XXX，具体议程将另行通知。</p><p style=\\\"text-align: start;\\\">XX公司行政部</p><p style=\\\"text-align: start;\\\">XXXX年XX月XX日</p>\",\"type\":1,\"level\":1,\"status\":1,\"receiverIds\":[]}', 200, '请求成功', 400, '2024-04-28 11:38:03', '1');
INSERT INTO `sys_log_operation` VALUES (1784427000388780033, 'admin', '通知公告-新增', '192.168.10.131', 'ADD', '新增通知公告信息', 'POST', '/system/sys/notice/save', '{\"title\":\"关于员工春节假期安排的通知\",\"content\":\"<p style=\\\"text-align: start;\\\">全体员工：</p><p style=\\\"text-align: start;\\\"> &nbsp; &nbsp; &nbsp; 根据国家法定节假日规定，结合公司实际情况，现将XXXX年春节假期安排通知如下：XX月XX日至XX月XX日放假调休，共X天。XX月XX日（星期X）上班。请各位同事提前做好工作安排，确保工作交接无误。</p><p style=\\\"text-align: start;\\\">XX公司人事部</p><p style=\\\"text-align: start;\\\">XXXX年XX月XX日</p>\",\"type\":1,\"level\":1,\"status\":1,\"receiverIds\":[]}', 200, '请求成功', 15, '2024-04-28 11:38:44', '1');
INSERT INTO `sys_log_operation` VALUES (1784427119792226305, 'admin', '通知公告-新增', '192.168.10.131', 'ADD', '新增通知公告信息', 'POST', '/system/sys/notice/save', '{\"title\":\"关于公司新址搬迁的通知\",\"content\":\"<p style=\\\"text-align: start;\\\">各位同事：</p><p style=\\\"text-align: start;\\\"> &nbsp; &nbsp; &nbsp; 因业务发展需要，公司将于XX月XX日起正式搬迁至新址：XXX。请各位同事提前整理好个人物品，按照搬迁计划有序进行。新址环境优雅，设施完善，相信将为大家提供更好的工作环境。</p><p style=\\\"text-align: start;\\\">XX公司行政部</p><p style=\\\"text-align: start;\\\">XXXX年XX月XX日</p>\",\"type\":1,\"level\":1,\"status\":1,\"receiverIds\":[]}', 200, '请求成功', 11, '2024-04-28 11:39:13', '1');
INSERT INTO `sys_log_operation` VALUES (1784427642960347137, 'admin', '通知公告-新增', '192.168.10.131', 'ADD', '新增通知公告信息', 'POST', '/system/sys/notice/save', '{\"title\":\"关于开展员工健康体检的通知\",\"content\":\"<p style=\\\"text-align: start;\\\">全体员工：</p><p style=\\\"text-align: start;\\\"> &nbsp; &nbsp; &nbsp; 为关爱员工身体健康，公司决定于XX月XX日组织全体员工进行健康体检。请各位同事安排好个人时间，按照通知要求前往指定医院进行体检。如有疑问，请咨询人事部。</p><p style=\\\"text-align: start;\\\">XX公司人事部</p><p style=\\\"text-align: start;\\\">XXXX年XX月XX日</p>\",\"type\":1,\"level\":1,\"status\":1,\"receiverIds\":[]}', 200, '请求成功', 21, '2024-04-28 11:41:17', '1');
INSERT INTO `sys_log_operation` VALUES (1784427738183630851, 'admin', '通知公告-新增', '192.168.10.131', 'ADD', '新增通知公告信息', 'POST', '/system/sys/notice/save', '{\"title\":\"关于公司团建活动活动的通知\",\"content\":\"<p style=\\\"text-align: start;\\\">各位同事：</p><p style=\\\"text-align: start;\\\"> &nbsp; &nbsp; &nbsp; 为增进员工之间的交流与沟通，提升团队凝聚力，公司定于XX月XX日组织团建活动活动。活动地点为XXX，具体安排将提前通知。请各位同事积极参与，共同度过一个愉快的周末。</p><p style=\\\"text-align: start;\\\">XX公司行政部</p><p style=\\\"text-align: start;\\\">XXXX年XX月XX日</p>\",\"type\":1,\"level\":1,\"status\":1,\"receiverIds\":[]}', 200, '请求成功', 13, '2024-04-28 11:41:40', '1');
INSERT INTO `sys_log_operation` VALUES (1784427842512748545, 'admin', '通知公告-新增', '192.168.10.131', 'ADD', '新增通知公告信息', 'POST', '/system/sys/notice/save', '{\"title\":\"关于公司内部培训课程的通知\",\"content\":\"<p style=\\\"text-align: start;\\\">各位同事：</p><p style=\\\"text-align: start;\\\"> &nbsp; &nbsp; &nbsp; 为提升员工专业技能与素质，公司将于XX月XX日起开设内部培训课程。课程内容包括但不限于XXX，请各位同事根据自身需求选择参加。具体课程安排与报名方式将另行通知。</p><p style=\\\"text-align: start;\\\">XX公司人事部</p><p style=\\\"text-align: start;\\\">XXXX年XX月XX日</p>\",\"type\":1,\"level\":1,\"status\":1,\"receiverIds\":[]}', 200, '请求成功', 20, '2024-04-28 11:42:05', '1');
INSERT INTO `sys_log_operation` VALUES (1784427946674094081, 'admin', '通知公告-新增', '192.168.10.131', 'ADD', '新增通知公告信息', 'POST', '/system/sys/notice/save', '{\"title\":\"关于公司年会筹备工作的通知\",\"content\":\"<p style=\\\"text-align: start;\\\">各位同事：</p><p style=\\\"text-align: start;\\\"> &nbsp; &nbsp; &nbsp; 为庆祝公司成立XX周年，公司将于XX月XX日举办年会活动。现开始筹备工作，请各部门负责人积极组织员工参与节目表演、抽奖等环节。同时，欢迎提供创意与建议，共同打造一场精彩纷呈的年会。</p><p style=\\\"text-align: start;\\\">XX公司行政部</p><p style=\\\"text-align: start;\\\">XXXX年XX月XX日</p>\",\"type\":1,\"level\":1,\"status\":1,\"receiverIds\":[]}', 200, '请求成功', 10, '2024-04-28 11:42:30', '1');
INSERT INTO `sys_log_operation` VALUES (1784428034997747713, 'admin', '通知公告-新增', '192.168.10.131', 'ADD', '新增通知公告信息', 'POST', '/system/sys/notice/save', '{\"title\":\"关于公司规章制度修订的通知\",\"content\":\"<p style=\\\"text-align: start;\\\">全体员工：</p><p style=\\\"text-align: start;\\\"> &nbsp; &nbsp; &nbsp; 为更好地规范公司管理，提高工作效率，公司近期对规章制度进行了修订。请各位同事认真阅读新修订的规章制度，并严格遵守。如有疑问，请及时向人事部咨询。</p><p style=\\\"text-align: start;\\\">XX公司人事部</p><p style=\\\"text-align: start;\\\">XXXX年XX月XX日</p>\",\"type\":1,\"level\":1,\"status\":1,\"receiverIds\":[]}', 200, '请求成功', 33, '2024-04-28 11:42:51', '1');
INSERT INTO `sys_log_operation` VALUES (1784428125091397634, 'admin', '通知公告-新增', '192.168.10.131', 'ADD', '新增通知公告信息', 'POST', '/system/sys/notice/save', '{\"title\":\"关于表彰优秀员工的通知\",\"content\":\"<p style=\\\"text-align: start;\\\">各位同事：</p><p style=\\\"text-align: start;\\\"> &nbsp; &nbsp; &nbsp; 在过去的一年里，公司涌现出了一批表现突出的优秀员工。为表彰他们的辛勤付出与优异成绩，公司决定对以下员工进行表彰：XXX等。希望受到表彰的员工继续努力，为公司的发展做出更大贡献。</p><p style=\\\"text-align: start;\\\">XX公司管理层</p><p style=\\\"text-align: start;\\\">XXXX年XX月XX日</p>\",\"type\":1,\"level\":1,\"status\":1,\"receiverIds\":[]}', 200, '请求成功', 11, '2024-04-28 11:43:12', '1');
INSERT INTO `sys_log_operation` VALUES (1784428204430852099, 'admin', '通知公告-新增', '192.168.10.131', 'ADD', '新增通知公告信息', 'POST', '/system/sys/notice/save', '{\"title\":\"关于公司新项目启动的通知\",\"content\":\"<p style=\\\"text-align: start;\\\">各位同事：</p><p style=\\\"text-align: start;\\\"> &nbsp; &nbsp; &nbsp; 经过前期筹备与市场调研，公司即将启动新项目——XXX。该项目将为公司带来新的发展机遇与挑战。请各部门负责人积极组织员工参与项目前期工作，确保项目顺利推进。具体工作安排将另行通知。</p><p style=\\\"text-align: start;\\\">XX公司管理层</p><p style=\\\"text-align: start;\\\">XXXX年XX月XX日</p>\",\"type\":1,\"level\":1,\"status\":1,\"receiverIds\":[]}', 200, '请求成功', 10, '2024-04-28 11:43:31', '1');
INSERT INTO `sys_log_operation` VALUES (1784428445590749186, 'admin', '通知公告-新增', '192.168.10.131', 'ADD', '新增通知公告信息', 'POST', '/system/sys/notice/save', '{\"title\":\"关于公司新产品发布的公告\",\"content\":\"<p style=\\\"text-align: start;\\\">尊敬的客户与合作伙伴：</p><p style=\\\"text-align: start;\\\"> &nbsp; &nbsp; &nbsp; 我们荣幸地宣布，公司即将推出全新产品——XXX。该产品结合了先进的技术与创新理念，旨在为用户带来更为便捷、高效的使用体验。具体发布时间与销售渠道将另行通知，敬请期待。</p><p style=\\\"text-align: start;\\\">XX公司市场部</p><p style=\\\"text-align: start;\\\">XXXX年XX月XX日</p>\",\"type\":2,\"level\":1,\"status\":1,\"receiverIds\":[]}', 200, '请求成功', 12, '2024-04-28 11:44:29', '1');
INSERT INTO `sys_log_operation` VALUES (1784428551278821379, 'admin', '通知公告-新增', '192.168.10.131', 'ADD', '新增通知公告信息', 'POST', '/system/sys/notice/save', '{\"title\":\"关于公司股票回购计划的公告\",\"content\":\"<p style=\\\"text-align: start;\\\">各位股东：</p><p style=\\\"text-align: start;\\\"> &nbsp; &nbsp; &nbsp; 为进一步提升公司价值，维护股东利益，公司决定启动股票回购计划。回购计划的具体细节将依据相关法律法规和公司章程进行，并及时向各位股东披露。敬请关注后续公告。</p><p style=\\\"text-align: start;\\\">XX公司财务部</p><p style=\\\"text-align: start;\\\">XXXX年XX月XX日</p>\",\"type\":2,\"level\":1,\"status\":1,\"receiverIds\":[]}', 200, '请求成功', 9, '2024-04-28 11:44:54', '1');
INSERT INTO `sys_log_operation` VALUES (1784428634896465923, 'admin', '通知公告-新增', '192.168.10.131', 'ADD', '新增通知公告信息', 'POST', '/system/sys/notice/save', '{\"title\":\"关于公司办公环境优化升级的公告\",\"content\":\"<p style=\\\"text-align: start;\\\">各位同事：</p><p style=\\\"text-align: start;\\\"> &nbsp; &nbsp; &nbsp; 为营造更为舒适、高效的办公环境，公司决定对办公区域进行优化升级。升级工作将包括空间布局调整、办公设施更新等。请各位同事配合相关安排，共同打造更美好的工作环境。</p><p style=\\\"text-align: start;\\\">XX公司行政部</p><p style=\\\"text-align: start;\\\">XXXX年XX月XX日</p>\",\"type\":2,\"level\":1,\"status\":1,\"receiverIds\":[]}', 200, '请求成功', 8, '2024-04-28 11:45:14', '1');
INSERT INTO `sys_log_operation` VALUES (1784428721190076418, 'admin', '通知公告-新增', '192.168.10.131', 'ADD', '新增通知公告信息', 'POST', '/system/sys/notice/save', '{\"title\":\"关于公司参与社会公益活动的公告\",\"content\":\"<p style=\\\"text-align: start;\\\">尊敬的客户与合作伙伴：</p><p style=\\\"text-align: start;\\\"> &nbsp; &nbsp; &nbsp; 为积极履行社会责任，公司决定参与XXX社会公益活动。我们将通过捐款、志愿服务等形式，为社会贡献一份力量。同时，我们也呼吁广大员工和合作伙伴积极参与，共同传递正能量。</p><p style=\\\"text-align: start;\\\">XX公司公关部</p><p style=\\\"text-align: start;\\\">XXXX年XX月XX日</p>\",\"type\":2,\"level\":1,\"status\":1,\"receiverIds\":[]}', 200, '请求成功', 15, '2024-04-28 11:45:34', '1');
INSERT INTO `sys_log_operation` VALUES (1784428798348492802, 'admin', '通知公告-新增', '192.168.10.131', 'ADD', '新增通知公告信息', 'POST', '/system/sys/notice/save', '{\"title\":\"关于公司年度供应商评选结果的公告\",\"content\":\"<p style=\\\"text-align: start;\\\">各位供应商伙伴：</p><p style=\\\"text-align: start;\\\"> &nbsp; &nbsp; &nbsp; 经过严格评选，公司XXXX年度优秀供应商名单已确定。在此，我们对以下供应商表示衷心感谢与高度认可：XXX。希望各位供应商继续与我们携手合作，共创美好未来。</p><p style=\\\"text-align: start;\\\">XX公司采购部</p><p style=\\\"text-align: start;\\\">XXXX年XX月XX日</p>\",\"type\":2,\"level\":1,\"status\":1,\"receiverIds\":[]}', 200, '请求成功', 9, '2024-04-28 11:45:53', '1');
INSERT INTO `sys_log_operation` VALUES (1784428880284221442, 'admin', '通知公告-新增', '192.168.10.131', 'ADD', '新增通知公告信息', 'POST', '/system/sys/notice/save', '{\"title\":\"关于公司开展节能减排工作的公告\",\"content\":\"<p style=\\\"text-align: start;\\\">全体员工：</p><p style=\\\"text-align: start;\\\"> &nbsp; &nbsp; &nbsp; 为响应国家节能减排号召，公司决定开展节能减排工作。我们将通过优化生产流程、采用节能设备等措施，降低能源消耗和碳排放。请各位同事积极参与，共同为环保事业贡献力量。</p><p style=\\\"text-align: start;\\\">XX公司环保部</p><p style=\\\"text-align: start;\\\">XXXX年XX月XX日</p>\",\"type\":2,\"level\":1,\"status\":1,\"receiverIds\":[]}', 200, '请求成功', 54, '2024-04-28 11:46:12', '1');
