INSERT INTO `sys_log_operation` VALUES (1818110524106874881, 'admin', '通知公告-草稿修改', '192.168.10.131', 'UPDATE', '修改通知公告草稿信息', 'PUT', '/system/sys/notice/update', '{\"sysNoticeId\":1784428880217112577,\"title\":\"关于公司开展节能减排工作的公告\",\"content\":\"<p style=\\\"text-align: start;\\\">全体员工：</p><p style=\\\"text-align: start;\\\"> &nbsp; &nbsp; &nbsp; 为响应国家<strong>节能减</strong>排号召，公司决定开展节能<span style=\\\"color: rgb(255, 77, 79);\\\">减排工</span>作。我们将通过优化生产流程、采用节能设备等措施，降低能源消耗和碳排放。请各位同事积极参与，共同为环保事业贡献力量。</p><p style=\\\"text-align: start;\\\">XX公司环保部</p><p style=\\\"text-align: start;\\\">XXXX年XX月XX日</p>\",\"type\":\"2\",\"level\":\"1\",\"status\":1,\"receiverIds\":[]}', 200, '请求成功', 236, '2024-07-30 10:25:02', '1');
